{
  "bioavailability_prediction": "low",
  "claims": [
    {
      "card_ids": ["C16"],
      "claim": "Retosiban, the highest-transfer analogue, had absolute oral bioavailability of 17–25% in healthy female subjects and was interpreted as extensive first-pass elimination; this does not affirmatively exceed the 20% threshold and supports low F.",
      "evidence_role": "supportive"
    },
    {
      "card_ids": ["C25"],
      "claim": "Olcegepant, a large peptidomimetic CGRP antagonist, had absolute oral bioavailability <1% in humans, showing that complex peptide-like structures can have extremely low F.",
      "evidence_role": "supportive"
    },
    {
      "card_ids": ["C08"],
      "claim": "Almorexant had absolute oral bioavailability of 11.2% (90% CI 9.6–13.1%) in healthy subjects, clearly below the 20% threshold.",
      "evidence_role": "supportive"
    },
    {
      "card_ids": ["C04"],
      "claim": "Docetaxel had absolute oral bioavailability of 8% ± 6% in patients, below the threshold, attributed to first-pass metabolism and P-glycoprotein efflux.",
      "evidence_role": "supportive"
    },
    {
      "card_ids": ["C12"],
      "claim": "UK-427,857 had oral bioavailability of 2.9 ± 1.7% in humans, far below the threshold.",
      "evidence_role": "supportive"
    },
    {
      "card_ids": ["C21"],
      "claim": "Dalfopristin, a macrocyclic peptidomimetic antibiotic, had absolute bioavailability <5%.",
      "evidence_role": "supportive"
    }
  ],
  "confidence": "high",
  "decision_summary": "All transferable experimental evidence points to low absolute oral bioavailability: quantitative F values from multiple peptidomimetic and complex drug scaffolds are below 20% (mostly 2.9–13%, with the highest analogue at 17–25% and interpreted as extensive first-pass elimination). The query's macrocyclic peptide-like structure with multiple amides, a carbamate, and a sulfonamide is consistent with poor permeability and high first-pass metabolism. Therefore, F < 20% is better supported.",
  "evidence_gaps": [
    "No direct absolute bioavailability measurement for the query molecule itself.",
    "The highest-transfer analogue (retosiban) has a borderline range spanning 20%, so threshold classification is not fully resolved.",
    "No high-F analogue was retrieved; all evidence is unidirectional low.",
    "Potential for the query's specific cyclopropyl sulfonamide and macrocyclic design to improve F is not directly tested."
  ],
  "new_evidence_assessment": [],
  "revision_action": "initial"
}

